module smallest_enclosing_ball_3d
import math
struct P{x f64;y f64;z f64}
struct S{c P;r f64}
fn sub(a P,b P) P{return P{a.x-b.x,a.y-b.y,a.z-b.z}} fn add(a P,b P) P{return P{a.x+b.x,a.y+b.y,a.z+b.z}} fn mul(a P,k f64) P{return P{a.x*k,a.y*k,a.z*k}} fn dot(a P,b P) f64{return a.x*b.x+a.y*b.y+a.z*b.z} fn cross(a P,b P) P{return P{a.y*b.z-a.z*b.y,a.z*b.x-a.x*b.z,a.x*b.y-a.y*b.x}} fn det(a P,b P,c P) f64{return dot(a,cross(b,c))} fn invalid() S{return S{P{},-1}}
fn through(p []P) S{if p.len==1{return S{p[0],0}}if p.len==2{c:=mul(add(p[0],p[1]),0.5);d:=sub(p[0],c);return S{c,math.sqrt(dot(d,d))}}if p.len==3{u:=sub(p[1],p[0]);v:=sub(p[2],p[0]);w:=cross(u,v);den:=2*dot(w,w);if den<1e-24{return invalid()};off:=mul(add(mul(cross(v,w),dot(u,u)),mul(cross(w,u),dot(v,v))),1/den);c:=add(p[0],off);d:=sub(c,p[0]);return S{c,math.sqrt(dot(d,d))}}a:=mul(sub(p[1],p[0]),2);b:=mul(sub(p[2],p[0]),2);c:=mul(sub(p[3],p[0]),2);qa:=dot(p[1],p[1])-dot(p[0],p[0]);qb:=dot(p[2],p[2])-dot(p[0],p[0]);qc:=dot(p[3],p[3])-dot(p[0],p[0]);d:=det(a,b,c);if math.abs(d)<1e-18{return invalid()};center:=mul(add(add(mul(cross(b,c),qa),mul(cross(c,a),qb)),mul(cross(a,b),qc)),1/d);delta:=sub(center,p[0]);return S{center,math.sqrt(dot(delta,delta))}}
fn contains(s S,p P) bool{if s.r<0{return false};d:=sub(p,s.c);return dot(d,d)<=(s.r+1e-10)*(s.r+1e-10)}
fn fit(r [4]P,m int) S{mut best:=invalid();for mask in 1..(1<<m){mut q:=[]P{};for i in 0..m{if mask&(1<<i)!=0{q<<r[i]}};s:=through(q);if s.r<0{continue};mut ok:=true;for i in 0..m{if !contains(s,r[i]){ok=false}};if ok&&(best.r<0||s.r<best.r-1e-12){best=s}};return best}
fn welzl(p []P,n int,mut r [4]P,m int) S{if n==0||m==4{return fit(r,m)};s:=welzl(p,n-1,mut r,m);if contains(s,p[n-1]){return s};r[m]=p[n-1];return welzl(p,n-1,mut r,m+1)}
@[export:'smallest_enclosing_ball_3d']
pub fn smallest_enclosing_ball_3d(input &f64,length usize,mut output &f64,capacity usize) i64{unsafe{if input==nil||length<4||length>25{return -1};raw:=input[0];if !math.is_finite(raw)||raw<1||raw>8||raw!=math.floor(raw){return -1};n:=int(raw);if length!=usize(1+3*n){return -1};mut p:=[]P{cap:n};for i in 0..n{q:=P{input[1+3*i],input[2+3*i],input[3+3*i]};if !math.is_finite(q.x)||!math.is_finite(q.y)||!math.is_finite(q.z)||math.abs(q.x)>10||math.abs(q.y)>10||math.abs(q.z)>10{return -1};p<<q};p.sort_with_compare(fn(a &P,b &P)int{if a.x!=b.x{return if a.x<b.x{-1}else{1}};if a.y!=b.y{return if a.y<b.y{-1}else{1}};return if a.z<b.z{-1}else if a.z>b.z{1}else{0}});mut r:=[4]P{};s:=welzl(p,n,mut r,0);if s.r<0||!math.is_finite(s.r){return -1};if output==nil||capacity<4{return -2};output[0]=s.c.x;output[1]=s.c.y;output[2]=s.c.z;output[3]=s.r;return 4}}
